#include "resident/domains/tasks/task_source_projection.hpp"
// 只按不可变marker解释独立新段；未选择时孤立新事实拒绝，不能从空表猜测启用或迁移旧银行。
#include "task_personal_message_profile.hpp"
#include <set>
namespace hanmo::resident {
Outcome<bool> decode_task_personal_message_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){try{using namespace boundary;const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find("task_personal_message_deliveries"):nullptr;if(!block){if(const auto* p=scenario.find("task_message_handoff_profile");p&&(string(*p,"task_message_handoff_profile")=="known_personal_delivery_and_report_v3"||string(*p,"task_message_handoff_profile")=="known_personal_delivery_and_sender_report_v4"))fail("TaskPersonalMessageProfileRequired","task_personal_message_deliveries");return {true,false,{}};}fields(*block,{"version","profile","policies"},{},"task_personal_message_deliveries");if(get_int(*block,"version","task_personal_message_deliveries")!=1||get_string(*block,"profile","task_personal_message_deliveries")!=task_personal_message_profile)unsupported("UnsupportedTaskPersonalMessageProfile","task_personal_message_deliveries");for(const auto* cap:{task_personal_message_capability,"native_dynamic_world","multi_actor","dialogue","tasks.message","task_message_handoffs_v1","task_message_reports_v2","task_static_assets_v1","family_life_v1","known_personal_dialogues_v1"})if(std::find(caps.begin(),caps.end(),cap)==caps.end())fail("TaskPersonalMessageCapabilityRequired",cap);if(scenario.find("task_message_notices"))fail("TaskPersonalMessageNoticeProfileUnsupported","task_message_notices");const auto handoff=get_string(scenario,"task_message_handoff_profile","scenario");if(handoff=="known_personal_delivery_and_sender_report_v4"){const auto* report=dynamic->find("task_personal_message_reports");if(!report||get_int(*report,"version","task_personal_message_reports")!=1||get_string(*report,"profile","task_personal_message_reports")!="known_private_sender_report_v1"||std::find(caps.begin(),caps.end(),"task_personal_message_reports_v1")==caps.end())fail("TaskPersonalReportProfileRequired","task_personal_message_reports");}else if(dynamic->find("task_personal_message_reports"))fail("TaskPersonalReportHandoff4Required","task_personal_message_reports");if((handoff!="known_personal_delivery_and_report_v3"&&handoff!="known_personal_delivery_and_sender_report_v4")||get_string(scenario,"task_static_asset_profile","scenario")!="original_task_assets_v1"||scenario.find("task_message_returns"))fail("TaskPersonalMessageOriginalSourcesRequired","scenario");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}

Outcome<Integer> task_personal_message_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){std::set<StableId> seen;std::map<StableId,StableId> versions;for(const auto& row:modules){if(!seen.insert(row.first).second)return {false,{},common_failure("DuplicateNativeModuleIdentity",row.first).error};versions[row.first]=row.second;}auto chosen=versions.find(task_personal_message_module);if(chosen==versions.end()){if((versions["task_message_handoffs"]=="3"||versions["task_message_handoffs"]=="4"||versions.count("task_personal_message_reports")))return {false,{},common_failure("TaskPersonalMessageProfileRequired").error};return {true,0,{}};}if(chosen->second!="1")return {false,{},common_failure("UnsupportedTaskPersonalMessageVersion").error};const bool reports=versions.count("task_personal_message_reports")!=0;if(reports&&versions["task_personal_message_reports"]!="1")return {false,{},common_failure("UnsupportedTaskPersonalReportVersion").error};for(const auto& pair:std::vector<std::pair<StableId,StableId>>{{"task_message_handoffs",reports?"4":"3"},{"task_static_assets","1"},{"family_life","1"},{"known_personal_dialogues","1"}}){auto found=versions.find(pair.first);if(found==versions.end()||found->second!=pair.second)return {false,{},common_failure("TaskPersonalMessageOriginalSourcesRequired",pair.first).error};}if(versions.count("task_message_notices"))return {false,{},common_failure("TaskPersonalMessageNoticeProfileUnsupported").error};if(versions.count("task_message_returns"))return {false,{},common_failure("TaskPersonalMessageReturnProfileUnsupported").error};return {true,1,{}};}
Status validate_task_personal_message_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const TaskPersonalMessageState* state){auto version=task_personal_message_selected_version(modules);if(!version.ok)return {false,{},version.error};if(bool(version.value)!=(state!=nullptr)||(state&&state->version!=1))return common_failure("TaskPersonalMessageProfileMismatch");if(!state)for(const auto& row:c.state().facts.rows())if(row.second.domain==task_personal_message_module||row.second.kind==task_personal_message_started_kind||row.second.kind==task_personal_message_delivered_kind||row.second.kind==task_personal_message_interrupted_kind)return common_failure("TaskPersonalMessageProfileRequired",row.first);return common_success();}
Outcome<bool> emit_task_personal_message_fact_payload_fields(ProjectionWriter& w,const TaskPersonalMessageState* state,const FactRecord& h){const bool known=h.kind==task_personal_message_started_kind||h.kind==task_personal_message_delivered_kind||h.kind==task_personal_message_interrupted_kind;if(!known&&h.domain!=task_personal_message_module)return {true,false,{}};if(!state||!known||h.domain!=task_personal_message_module)return {false,{},common_failure("TaskPersonalMessageFactMismatch",h.id).error};auto status=emit_task_personal_message_fact_fields(w,*state,h.id);if(!status.ok)return {false,{},status.error};w.field("kind",h.kind);w.field("domain",h.domain);return {w.status().ok,w.status().ok,w.status().error};}
Status emit_task_personal_message_fact_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskPersonalMessageState* state){std::size_t emitted=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool known=h.kind==task_personal_message_started_kind||h.kind==task_personal_message_delivered_kind||h.kind==task_personal_message_interrupted_kind;if(!known&&h.domain!=task_personal_message_module)continue;if(!state||!known||h.id!=row.first||h.domain!=task_personal_message_module)return common_failure("TaskPersonalMessageFactMismatch",row.first);auto checked=w.object(row.first,[&](auto&out){auto status=emit_task_personal_message_fact_fields(out,*state,row.first);if(!status.ok)return status;out.field("kind",h.kind);out.field("domain",h.domain);return out.status();});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->starts.size()+state->endings.size())return common_failure("TaskPersonalMessageFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> task_personal_message_fact_payloads(const CommonStore& c,const TaskPersonalMessageState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_personal_message_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_task_personal_message_json_payloads(const CommonStore& c,const TaskPersonalMessageState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=task_personal_message_fact_payloads(c,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"task_personal_message_deliveries/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("TaskPersonalMessageFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
